class BaseStore {
  protected items: Book[] = [];
}

export class BookStore extends BaseStore {
  add(book: Book): void {
    this.items.push(book);
  }
}

import { useState } from 'react';
import type { Book } from './api';

export function useBookStore() {
  const [books, setBooks] = useState<Book[]>([]);
  return { books, setBooks };
}

import React from 'react';

export class App extends React.Component {
  render() {
    return <main>Hello</main>;
  }
}

import type { Book } from './api';

interface Props {
  book: Book;
}

export const BookCard = (props: Props): JSX.Element => {
  return <article>{props.book.title}</article>;
};

// class BookStore extends Store — refactored to composition
export function createBookStore(): { books: Book[] } {
  return { books: [] };
}

export function errorMessage(): string {
  return 'class BookStore extends BaseStore is not allowed';
}

